-- Repeat-safe quiz ownership/submission metadata. Existing questions are preserved.
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='quizzes' AND column_name='difficulty')=0,'ALTER TABLE quizzes ADD COLUMN difficulty VARCHAR(20) NOT NULL DEFAULT ''medium'' AFTER topic','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='quizzes' AND column_name='language')=0,'ALTER TABLE quizzes ADD COLUMN language VARCHAR(5) NOT NULL DEFAULT ''en'' AFTER difficulty','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='quizzes' AND column_name='quiz_batch_id')=0,'ALTER TABLE quizzes ADD COLUMN quiz_batch_id VARCHAR(36) NULL AFTER language','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='quizzes' AND column_name='submitted_at')=0,'ALTER TABLE quizzes ADD COLUMN submitted_at DATETIME NULL AFTER created_at','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='quizzes' AND index_name='idx_quizzes_batch_owner')=0,'ALTER TABLE quizzes ADD INDEX idx_quizzes_batch_owner (quiz_batch_id,user_id)','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
